@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap');

@tailwind base;
@tailwind components;
@tailwind utilities;

@layer base {
  html {
    @apply scroll-smooth;
  }

  body {
    @apply bg-gray-950 text-gray-100 antialiased;
  }

  /* Focus ring for keyboard navigation */
  :focus-visible {
    @apply outline-2 outline-offset-2 outline-brand rounded-sm;
  }
}

@layer components {
  .nav-link {
    @apply text-gray-400 hover:text-white transition-colors duration-200 text-sm font-medium;
  }

  .nav-link.active {
    @apply text-white;
  }

  .btn-primary {
    @apply inline-flex items-center gap-2 px-6 py-3 bg-brand text-gray-950 font-semibold rounded-lg
           hover:bg-emerald-400 transition-colors duration-200 focus-visible:outline-brand;
  }

  .section {
    @apply px-6 py-16 md:py-24 max-w-5xl mx-auto;
  }

  .card {
    @apply bg-gray-900 border border-gray-800 rounded-xl p-6 md:p-8;
  }
}

